```python
def f(inputs: List[Tuple[int, str]]):
    result = []
    for n, s in inputs:
        nums = []
        ops = []
        num = 0
        for c in s:
            if c.isdigit():
                num = num * 10 + int(c)
            else:
                nums.append(num)
                num = 0
                ops.append(c)
        nums.append(num)
        nums = nums[::-1]
        stack = []
        for _ in range(n):
            while nums:
                num = nums.pop()
                if num == '(':
                    stack.append(nums.pop())
                else:
                    stack.append(num)
            while len(stack) > 1:
                op = stack.pop()
                if op == ')':
                    break
                op1 = stack.pop()
                op2 = stack.pop()
                if op == '+':
                    stack.append(op1 + op2)
                else:
                    stack.append(op1 * op2)
        result.append(stack[0])
    return result


inputs = [(3, "(1+2)*3+3"), (2, "1*1*1+1*1*1"), (587, "1*(2*3*4)+5+((6+7*8))*(9)"), (0, "0")]

print(f(inputs))
```

